mapper.insert:
INSERT INTO courses (
    title, user_id, content, created_at, deleted
) VALUES (
             #{title}, #{userId}, #{content}, NOW(), 0
         )

INSERT INTO course_images (
    course_id, image_url, uploaded_at, deleted
) VALUES (
             #{courseId}, #{imageUrl}, NOW(), 0
         )

INSERT INTO course_destinations (
    course_id, destination_id, visit_order
) VALUES (
             #{courseId}, #{destinationId}, #{visitOrder}
         )
